  "gdprCenter.section.controller.b1": "Áp dụng cho quyền dữ liệu EEA/UK và các nghĩa vụ tin cậy liên quan",
  "gdprCenter.section.controller.b2": "Kết nối các quyền hợp pháp với quy trình sản phẩm và hỗ trợ thực tế",
  "gdprCenter.section.controller.b3": "Được xây dựng để giúp cả người dùng và người đánh giá tuân thủ hiểu nhanh hệ thống",
  "gdprCenter.section.controller.p1": "RealAICoach đóng vai trò là người kiểm soát dữ liệu tài khoản nền tảng, sản phẩm, hỗ trợ và dịch vụ liên kết trong phạm vi mà chúng tôi quyết định mục đích và phương tiện xử lý. Một số bộ xử lý hoạt động theo chỉ dẫn của chúng tôi dưới sự kiểm soát hợp đồng.",
  "gdprCenter.section.controller.p2": "Trang này tóm tắt cam kết của chúng tôi đối với GDPR về quyền truy cập, sửa đổi, xóa bỏ, di chuyển, phản đối, hạn chế và các cách liên lạc liên quan đến quyền riêng tư theo cách thực tế hơn so với một tài liệu pháp lý truyền thống.",
  "gdprCenter.section.controller.summary": "Giải thích vai trò của chúng tôi là người kiểm soát, các danh mục dữ liệu thuộc phạm vi và lý do áp dụng GDPR.",
  "gdprCenter.section.controller.title": "Người kiểm soát, phạm vi và khung pháp lý",
  "gdprCenter.section.focus": "Phần ghim",
  "gdprCenter.section.lawful.p1": "Cơ sở hợp pháp chính của chúng tôi bao gồm thực hiện hợp đồng, lợi ích hợp pháp, sự đồng ý và nghĩa vụ pháp lý tùy thuộc vào danh mục dữ liệu và quy trình làm việc liên quan.",
  "gdprCenter.section.lawful.p2": "Khi có sự đồng ý, người dùng có thể rút lại. Khi lợi ích hợp pháp được sử dụng, chúng tôi nhằm giữ cho việc xử lý tương xứng, có thể giải thích và hạn chế theo nhu cầu hoạt động đã nêu.",
  "gdprCenter.section.lawful.summary": "Dữ liệu cá nhân chỉ được xử lý khi có một cơ sở hợp pháp hỗ trợ cho mục đích.",
  "gdprCenter.section.lawful.title": "Cơ sở hợp pháp cho việc xử lý",
  "gdprCenter.section.rights.b1": "Xuất hoặc xóa thông qua cổng yêu cầu quyền riêng tư đã được xác minh",
  "gdprCenter.section.rights.b2": "Liên hệ với nhóm quyền riêng tư để yêu cầu sửa đổi, phản đối hoặc hạn chế",
  "gdprCenter.section.rights.b3": "Tăng cường lên cơ quan giám sát khi được pháp luật yêu cầu",
  "gdprCenter.section.rights.p1": "Người dùng có thể yêu cầu truy cập dữ liệu cá nhân, sửa đổi dữ liệu không chính xác, xóa bỏ khi được phép, di chuyển, hạn chế, phản đối và xem xét các lựa chọn liên quan đến sự đồng ý. Chúng tôi cũng cung cấp một lối đi tự phục vụ cho việc xuất và xác minh xóa bỏ.",
  "gdprCenter.section.rights.p2": "Khi một yêu cầu không thể hoàn thành chính xác như đã nộp, chúng tôi nhằm giải thích lý do, giới hạn pháp lý hoặc hoạt động nào áp dụng, và con đường thay thế nào có sẵn.",
  "gdprCenter.section.rights.summary": "Quyền truy cập, sửa đổi, xóa bỏ, di chuyển, phản đối, hạn chế và rút lại sự đồng ý được kết nối với các quy trình yêu cầu thực tế.",
  "gdprCenter.section.rights.title": "Quyền GDPR của bạn",
  "gdprCenter.section.transfers.p1": "Khi dữ liệu cá nhân được xử lý ngoài EEA hoặc Vương quốc Anh, chúng tôi dựa vào các biện pháp bảo vệ phù hợp như bảo vệ hợp đồng, nghĩa vụ của nhà cung cấp và các biện pháp kiểm soát an toàn phù hợp với ngữ cảnh xử lý.",
  "gdprCenter.section.transfers.p2": "Thời gian lưu giữ phụ thuộc vào nhu cầu sản phẩm, nghĩa vụ pháp lý, nhu cầu an ninh và các yêu cầu xóa đã được xác minh. Mục tiêu của chúng tôi là giữ cho thời gian lưu giữ dễ hiểu thay vì ẩn mình trong các khái niệm pháp lý mơ hồ.",
  "gdprCenter.section.transfers.summary": "Việc xử lý và lưu giữ xuyên biên giới được kiểm soát thông qua các biện pháp bảo vệ hợp đồng, kỹ thuật và hoạt động.",
  "gdprCenter.section.transfers.title": "Chuyển giao quốc tế, lưu giữ và biện pháp bảo vệ",
  "gdprCenter.sidebar.ctaBody": "Sử dụng lối đi yêu cầu quyền riêng tư đã được xác minh để xuất hoặc xóa, hoặc liên hệ với hoạt động quyền riêng tư để có các yêu cầu GDPR cụ thể hơn.",
